 e.itemComponentRegistry?.registerCustomComponent('ava:clay_bucket_use',{onUse:e=>{const p=e.source;if(inv(p)?.getItem(p.selectedSlotIndex)?.typeId!==e.itemStack?.typeId)return;const hit=p.getBlockFromViewDirection({maxDistance:5,includeLiquidBlocks:true});if(hit)clayBucketUse(p,hit.block,hit.face||'up');},onUseOn:e=>{if(inv(e.source)?.getItem(e.source.selectedSlotIndex)?.typeId===e.itemStack?.typeId)clayBucketUse(e.source,e.block,e.blockFace||'up');}});
