 if(!['oak','birch','spruce','jungle','acacia','dark_oak','cherry','pale_oak','mangrove'].includes(species))return false;
 const placements=[];for(let y=0;y<4;y++)placements.push({x:b.x,y:b.y+y,z:b.z,id:'minecraft:'+species+'_log'});
 for(let y=2;y<=4;y++)for(let x=-2;x<=2;x++)for(let z=-2;z<=2;z++)if((x||z||y===4)&&Math.abs(x)+Math.abs(z)<(y===4?2:4))placements.push({x:b.x+x,y:b.y+y,z:b.z+z,id:'minecraft:'+species+'_leaves'});
 for(const loc of placements){let target;try{target=b.dimension.getBlock(loc);}catch{return false;}if(!target||(target.x!==b.x||target.y!==b.y||target.z!==b.z)&&target.typeId!=='minecraft:air'&&!naturalLeaf(target.typeId))return false;}
 for(const loc of placements){const target=b.dimension.getBlock(loc);target.setType(loc.id);if(loc.id.endsWith('_leaves'))try{target.setPermutation(target.permutation.withState('persistent_bit',true));}catch{}}
 return true;
