function bypassActivator(p){return !!p.isSneaking;}
world.beforeEvents.playerInteractWithEntity.subscribe(e=>{if(e.target.typeId!=='ava:activator_inventory')return;if(bypassActivator(e.player)){e.cancel=true;system.run(()=>armActivator(e.target,false));return;}activatorViewers.set(e.target.id,e.player);});
world.afterEvents.entityHitEntity.subscribe(e=>{if(e.hitEntity?.typeId==='ava:activator_inventory'){activatorMiningUntil.set(e.hitEntity.id,(system.currentTick||0)+60);armActivator(e.hitEntity,false);}});
interval268('interval L624',()=>{for(const [id,{host,b}]of activatorHosts){try{if(host.isValid===false){activatorHosts.delete(id);activatorViewers.delete(id);activatorArmed.delete(id);continue;}if(b.typeId!=='ava:autonomous_activator'){host.remove();activatorHosts.delete(id);activatorViewers.delete(id);continue;}const aimed=!!hudAimPlayer238(b);armActivator(host,aimed&&(activatorMiningUntil.get(id)||0)<=(system.currentTick||0));const viewer=activatorViewers.get(id);if(viewer||aimed)pollActivator(b,host,viewer);if(viewer&&(viewer.isValid===false||viewer.dimension.id!==b.dimension.id||Math.hypot(viewer.location.x-b.x,viewer.location.y-b.y,viewer.location.z-b.z)>8))activatorViewers.delete(id);}catch{activatorHosts.delete(id);activatorViewers.delete(id);activatorArmed.delete(id);}}
},2);

world.afterEvents.entityContainerClosed?.subscribe(nativeCloseHandler160(({entity,closeSource})=>{if(entity?.typeId!=='ava:activator_inventory')return;const p=closeSource?.entity;if(p)clearUiTokens(p);activatorViewers.delete(entity.id);}));

const rainComposters=new Map();let rainRegistryLoaded=false,rainScanStep=0;
function loadRainRegistry(){if(rainRegistryLoaded)return;rainRegistryLoaded=true;try{for(const [x,y,z]of JSON.parse(world.getDynamicProperty('ava:rain_composters')||'[]'))rainComposters.set([x,y,z].join(','),{x,y,z});}catch{}}
function saveRainRegistry(){world.setDynamicProperty('ava:rain_composters',JSON.stringify([...rainComposters.values()].map(p=>[p.x,p.y,p.z])));}
function trackComposter(b){if(b.dimension.id!=='minecraft:overworld'||!['minecraft:composter','ava:water_composter','ava:composting_composter'].includes(b.typeId))return;loadRainRegistry();const id=[b.x,b.y,b.z].join(',');if(!rainComposters.has(id)){rainComposters.set(id,{x:b.x,y:b.y,z:b.z});saveRainRegistry();}}
function raining(d){const weather=String(d.getWeather?.()||world.getDynamicProperty('ava:weather')||'Clear').toLowerCase();return weather==='rain'||weather==='thunder';}
function rainFill(b){if(!['minecraft:composter','ava:water_composter','ava:composting_composter'].includes(b.typeId)||b.dimension.id!=='minecraft:overworld'||!raining(b.dimension))return false;const s=state(b);if(s.waterLocked&&s.water>0)return false;if((s.dirt||0)>0||(s.clay||0)>0||(s.compost||0)>0||b.typeId==='minecraft:composter'&&(b.permutation.getState('composter_fill_level')||0)>0||(s.water||0)>=1000)return false;const top=b.dimension.getTopmostBlock({x:b.x,z:b.z});if(!top||top.y>b.y)return false;s.water=Math.min(1000,(s.water||0)+250);if(s.water>=1000)s.waterLocked=true;if(b.typeId!=='ava:water_composter')b.setType('ava:water_composter');b.setPermutation(b.permutation.withState('ava:water_level',Math.ceil(s.water/250)));save(b,s);return true;}
world.afterEvents.weatherChange.subscribe(e=>{if(e.dimension==='minecraft:overworld'||e.dimension==='overworld')world.setDynamicProperty('ava:weather',e.newWeather);});
world.afterEvents.playerPlaceBlock.subscribe(e=>{if(e.block.typeId==='ava:water_composter'&&!(state(e.block).water>0))e.block.setType('minecraft:composter');trackComposter(e.block);});
// Discover old nearby composters a few columns at a time, avoiding a world scan.
interval268('interval L638',()=>{const d=world.getDimension('overworld');loadRainRegistry();const wet=raining(d);if(wet){for(const p of packPlayers203()){if(p.dimension.id!==d.id)continue;for(let column=0;column<9;column++){const index=(rainScanStep+column)%81,dx=index%9-4,dz=Math.floor(index/9)-4;for(let dy=-3;dy<=3;dy++)try{trackComposter(d.getBlock({x:Math.floor(p.location.x)+dx,y:Math.floor(p.location.y)+dy,z:Math.floor(p.location.z)+dz}));}catch{}}}rainScanStep=(rainScanStep+9)%81;}
},20);
interval268('interval L640',()=>{loadRainRegistry();const d=world.getDimension('overworld');let removed=false;for(const [id,pos]of rainComposters)try{const b=d.getBlock(pos);if(!['minecraft:composter','ava:water_composter','ava:composting_composter'].includes(b.typeId)){rainComposters.delete(id);removed=true;continue;}rainFill(b);}catch{}if(removed)saveRainRegistry();},200);
const emptyBuckets=new Set(['minecraft:bucket','ava:clay_bucket']);
function exchangeBucket(p,from,to){const c=inv(p),slot=p.selectedSlotIndex,item=c?.getItem(slot);if(item?.typeId!==from)return false;if(item.amount===1)c.setItem(slot,new ItemStack(to));else{item.amount--;c.setItem(slot,item);give(p,to);}return true;}
function waterComposterUse(p,b){if(b.typeId==='ava:composting_composter')return false;const leaf=inv(p)?.getItem(p.selectedSlotIndex);if(isWaterLeaf(leaf?.typeId)){if(addLeafWater(b,leaf.typeId))take(p,leaf.typeId);return true;}if(inv(p)?.getItem(p.selectedSlotIndex)?.typeId==='minecraft:dirt'&&mixComposterMud(b)){take(p,'minecraft:dirt');deliverComposterResult(p,b,3);return true;}if(inv(p)?.getItem(p.selectedSlotIndex)?.typeId==='minecraft:sand'&&mixWitchSand(b)){take(p,'minecraft:sand');deliverComposterResult(p,b,2);return true;}if(stateValue240(b,"witchWater")){p.onScreenDisplay?.setActionBar('Witch Water | Add sand for Soul Sand');return true;}if(inv(p)?.getItem(p.selectedSlotIndex)?.typeId==='ava:dust'&&mixComposterClay(b)){take(p,'ava:dust');deliverComposterResult(p,b,1);return true;}trackComposter(b);const held=inv(p).getItem(p.selectedSlotIndex),s=state(b);if(emptyBuckets.has(held?.typeId)&&(s.water||0)>=1000){if(exchangeBucket(p,held.typeId,held.typeId==='ava:clay_bucket'?'ava:clay_water_bucket':'minecraft:water_bucket')){s.water=0;s.waterLocked=false;s.witchProgress=0;b.setType('minecraft:composter');save(b,s);}return true;}if(['ava:clay_water_bucket','minecraft:water_bucket'].includes(held?.typeId)&&!(s.dirt>0)&&!((s.clay>0||(s.soulSand>0||s.mud>0)))&&!(s.compost>0)&&!(s.water>0)&&!(b.permutation.getState('composter_fill_level')>0)){if(exchangeBucket(p,held.typeId,held.typeId.startsWith('ava:')?'ava:clay_bucket':'minecraft:bucket')){s.water=1000;s.waterLocked=true;b.setType('ava:water_composter');b.setPermutation(b.permutation.withState('ava:water_level',4));save(b,s);}return true;}if(b.typeId==='ava:water_composter'){p.onScreenDisplay?.setActionBar(waterComposterStatus(b));return true;}return false;}
function clayBucketUse(p,b,face='up'){if(b.typeId==='ava:seared_tank'){forgeUse(p,b);return true;}if(processorKinds.has(b.typeId))return processorUse(p,b);if(b.typeId==='ava:stone_barrel')return barrelUse(p,b);if(['ava:automated_sprinkler','ava:moisture_collector'].includes(b.typeId))return ecoMachineUse(p,b);if(b.typeId==='ava:magma_furnace')return magmaUse(p,b);const held=inv(p)?.getItem(p.selectedSlotIndex);if(!held?.typeId.startsWith('ava:clay_')||held.typeId==='ava:clay_bucket_unfired')return false;
 if(['minecraft:composter','ava:water_composter','ava:composting_composter'].includes(b.typeId)&&waterComposterUse(p,b))return true;
 if(b.typeId==='ava:tank')return tankBucketUse(p,b);
 if(b.typeId==='ava:kiln'){const s=state(b);if(held.typeId==='ava:clay_bucket'&&(s.lava||0)>=1000){if(exchangeBucket(p,held.typeId,'ava:clay_lava_bucket')){s.lava-=1000;save(b,s);}return true;}if(b.typeId==='ava:tank'&&held.typeId==='ava:clay_lava_bucket'&&(s.lava||0)<=15000){if(exchangeBucket(p,held.typeId,'ava:clay_bucket')){s.lava=(s.lava||0)+1000;save(b,s);}return true;}return true;}
 const fluid=['minecraft:water','minecraft:flowing_water'].includes(b.typeId)?'water':['minecraft:lava','minecraft:flowing_lava'].includes(b.typeId)?'lava':undefined;
 if(held.typeId==='ava:clay_bucket'&&fluid){if((b.permutation.getState('liquid_depth')||0)!==0)return true;if(exchangeBucket(p,held.typeId,'ava:clay_'+fluid+'_bucket')){b.setType('minecraft:air');invalidateNetworks();}return true;}
 const fill=held.typeId==='ava:clay_water_bucket'?'water':held.typeId==='ava:clay_lava_bucket'?'lava':undefined;if(!fill)return true;
 const target=b.typeId==='minecraft:air'?b:offsetBlock(b,face.toLowerCase());if(target?.typeId!=='minecraft:air')return true;
 if(exchangeBucket(p,held.typeId,'ava:clay_bucket')){if(fill==='water'&&b.dimension.id==='minecraft:nether')b.dimension.spawnParticle?.('minecraft:basic_smoke_particle',{x:target.x+.5,y:target.y+.5,z:target.z+.5});else target.setType('minecraft:flowing_'+fill);invalidateNetworks();}return true;
}
function seedFeedback(p,text,success=false){p[success?'result':'failure']=text;p.onScreenDisplay?.setActionBar(text);return success;}
function plantSkySeed(p,b,face='up'){const item=inv(p)?.getItem(p.selectedSlotIndex),id=item?.typeId,cane=id==='ava:sugar_cane_seeds',cactus=id==='ava:cactus_seeds',cocoa=id==='ava:cocoa_seeds';if(!cane&&!cactus&&!cocoa)return false;const soil=cocoa?['minecraft:jungle_log','minecraft:stripped_jungle_log']:cactus?['minecraft:sand','minecraft:red_sand']:['minecraft:dirt','minecraft:grass_block','minecraft:grass','minecraft:sand','minecraft:red_sand','minecraft:coarse_dirt','minecraft:rooted_dirt','minecraft:podzol','minecraft:mud'];if(!soil.includes(b.typeId)){seedFeedback(p,cocoa?'Cocoa Seeds: use the side of a Jungle Log':cactus?'Cactus Seeds: plant on Sand or Red Sand':'Sugar Cane Seeds: plant on Dirt or Sand beside water');return false;}face=String(face).toLowerCase();if(cocoa&&!['north','south','east','west'].includes(face)){seedFeedback(p,'Cocoa Seeds: use the SIDE of a Jungle Log');return false;}const target=offsetBlock(b,cocoa?face:'up');if(target.typeId!=='minecraft:air'){seedFeedback(p,'Planting blocked: clear the space above the soil');return false;}if(cactus&&near(target).some(n=>n.y===target.y&&n.typeId!=='minecraft:air')){seedFeedback(p,'Cactus needs clear space on all four sides');return false;}if(cane&&!near(b).some(n=>n.y===b.y&&(['minecraft:water','minecraft:flowing_water'].includes(n.typeId)||n.isWaterlogged===true))){seedFeedback(p,'Sugar Cane needs water directly BESIDE the soil at soil height');return false;}try{target.setType(cocoa?'minecraft:cocoa':cactus?'minecraft:cactus':'minecraft:reeds');if(cocoa)target.setPermutation(target.permutation.withState('direction',({north:0,south:2,east:1,west:3})[face]));}catch(error){seedFeedback(p,'Cannot plant here: '+error.message);return false;}if(!take(p,id)){target.setType('minecraft:air');return false;}return seedFeedback(p,cocoa?'Planted Cocoa':cactus?'Planted Cactus':'Planted Sugar Cane',true);}

