function placingAgainstMachine(p,hand,b){if(!hand)return false;if(hasMachineHud(b)&&!p.isSneaking)return false;if(forgeBlocks.has(b.typeId)&&!p.isSneaking&&(forgeRecipe(hand)||hand.typeId.startsWith("ava:cast_")||hand.typeId.startsWith("ava:pattern_")||["minecraft:coal","minecraft:blaze_powder"].includes(hand.typeId)))return false;if(processorKinds.has(b.typeId)&&processorAccepts(b,hand)&&!p.isSneaking)return false;if(isComposter(b)&&(isWaterLeaf(hand.typeId)||compostIngredient(hand.typeId))&&!p.isSneaking)return false;if(isComposter(b)&&['ava:dust','minecraft:sand','minecraft:dirt'].includes(hand.typeId))return false;if(b.typeId==='ava:black_hole_unit'&&!p.isSneaking)return false;if(b.typeId==='ava:stone_barrel'&&barrelProducts[hand.typeId])return false;if(b.typeId==='ava:combustion_generator'&&combustionFuel(hand.typeId)&&!p.isSneaking)return false;if(b.typeId==='ava:sieve'&&siftDrops[hand.typeId]&&!p.isSneaking)return false;let isBlock=false;try{isBlock=networkBlocks.has(hand.typeId)||!!BlockTypes.get(hand.typeId);}catch{}if(!isBlock)return false;return !(b.typeId==='ava:kiln'&&hand.typeId==='minecraft:cobblestone'&&!p.isSneaking);}

