function consumeAndPlace(player,id,place){
 const bag=inventory(player);
 for(let i=0;i<(bag?.size||0);i++){
  const item=bag.getItem(i);if(item?.typeId!==id||!api.canStore(item))continue;
  const before=item.clone(),remaining=item.amount-1;
  if(remaining){item.amount=remaining;bag.setItem(i,item);}else bag.setItem(i);
  try{place();return true;}catch(error){bag.setItem(i,before);throw error;}
 }
 // Resolve fresh accessible MV states per placement, with no awaited work
 // between removal and placement, so multiplayer pulls cannot use stale stock.
 for(const vault of api.vaults(player)){
  if((vault.state.counts?.[id]||0)<=0)continue;
  const before=JSON.parse(JSON.stringify(vault.state));
  if(api.remove(vault.state,id,1)!==1)continue;
  try{if(api.save(vault)===false)throw Error('MV could not save the material withdrawal');place();return true;}
  catch(error){vault.state=before;if(api.save(vault)===false)console.warn('Builder Wand: MV material rollback could not save');throw error;}
 }
 return false;
}
