const inlinePatterns=new Map(),inlineRecipeCache=new Map();
function inlineRecipe(cells){const key=JSON.stringify(cells);if(!inlineRecipeCache.has(key))inlineRecipeCache.set(key,inlineRecipeResolve(cells));return inlineRecipeCache.get(key);}
function inlineRecipeResolve(cells){const filled=cells.filter(Boolean);if(!filled.length)return;const norm=a=>{const pos=a.map((v,i)=>v?i:-1).filter(i=>i>=0),x=Math.min(...pos.map(i=>i%3)),y=Math.min(...pos.map(i=>Math.floor(i/3)));return a.reduce((r,v,i)=>{if(v)r[(Math.floor(i/3)-y)*3+i%3-x]=v;return r;},Array(9).fill(null));};const actual=norm(cells);
for(const r of crafterRecipes){const layout=patternLayouts[r.id];if(layout){for(const mirror of [false,true]){const expected=norm(layout.map((_,i)=>layout[mirror?Math.floor(i/3)*3+2-i%3:i]==null?null:r.ingredients[layout[mirror?Math.floor(i/3)*3+2-i%3:i]].options));if(expected.every((v,i)=>v?actual[i]&&v.includes(actual[i]):!actual[i]))return r;}}else{const counts={};for(const id of filled)counts[id]=(counts[id]||0)+1;let good=true;for(const q of r.ingredients){let n=q.count;for(const id of q.options){const take=Math.min(n,counts[id]||0);counts[id]=(counts[id]||0)-take;n-=take;}if(n){good=false;break;}}if(good&&Object.values(counts).every(n=>!n))return r;}}
}
