for(let i=0;i<9;i++){const old=c.getItem(18+i);if(old&&!fake(old))continue;if(cells[i]){if(old?.typeId===cells[i]&&old.getLore().includes('mv:inline:cell:'+i)&&old.amount===1)continue;const ghost=preview(cells[i]);ghost.amount=1;ghost.setLore([MARK,'mv:inline:ghost','mv:inline:cell:'+i]);c.setItem(18+i,ghost);}else if(old)c.setItem(18+i);}
