function pollInputRaw267(player,e){return withMvUiPass262(e,()=>{mvLastPoll262.set(e,system.currentTick);return pollInputRaw262(player,e);});}
function batchStockRefresh(e,run){return withMvUiPass262(e,()=>batchStockRefreshRaw262(e,run));}
function pollMvImmediate262(player,e){
 if(mvLastPoll262.get(e)===system.currentTick||!entityAlive(e)||!ownsNativeHud157(player,e))return false;
 const c=bag(e);let changed=false;
 for(const slot of[216,214,215,219,221,222,0,252,253])if(!c.getItem(slot)){changed=true;break;}
 if(!changed)for(const[entries,signalStart]of[[displayedEntries.get(e.id),152],[fullStorageEntries.get(e.id),182]]){const count=Math.min(45,entries?.length||0);for(let g=0;g<Math.ceil(count/3);g++)if(c.getItem(signalStart+g)?.amount!==64){changed=true;break;}if(changed)break;}
 if(!changed)return false;
 batchStockRefresh(e,()=>{pollInput(player,e);flushNativeQuickDeposits(e,player);flushNativeDragDeposits(e);});return true;
}

