 for(let group=0;group<30;group++){const slot=storageSignalSlot(group),token=c.getItem(slot);if(token?.typeId==='ava:mv_signal_token'&&token.amount===64)continue;if(!token&&takeSharedMvFind(e,c,slot,'storage',group,directSignals.has(slot)?slot:cursorSignalSlot))continue;if(token&&token.typeId!=='ava:mv_signal_token'&&!fake(token)){if(depositIncoming(e,slot)){c.setItem(slot,signal('storage',group,e));refreshStock(e);}}else if(token&&![64,32,63].includes(token.amount)){c.setItem(slot,signal('storage',group,e));}else if(!token||token.amount!==64){const index=group*3+(token?.amount===32?1:token?.amount===63?2:0),id=displayedEntries.get(e.id)?.[index]?.[0];c.setItem(slot,signal('storage',group,e));if(id)storageClicks.push(id);}}


