const anchors = new Map();
const reportedErrors = new Set();
let cursor = 0;

function forget(entity) {
  try { entity.getComponent('minecraft:equippable')?.setEquipment(EquipmentSlot.Mainhand, undefined); } catch {}
  try { entity.remove(); } catch {}
}

function syncBlackHoleDisplay(block, key, itemId, count = 0) {
  const location = { ...block.location };
  const dimension = block.dimension;
  // Keep the flattened hand model just outside the north panel, avoiding z-fighting.
  const face=block.permutation.getState('minecraft:cardinal_direction')||'north';
  const normals={north:[0,0,-1],south:[0,0,1],east:[1,0,0],west:[-1,0,0],up:[0,1,0],down:[0,-1,0]},normal=normals[face];
  const position={x:location.x+0.5+normal[0]*0.525,y:location.y+0.5+normal[1]*0.525,z:location.z+0.5+normal[2]*0.525};
  const yaw={north:180,south:0,east:90,west:-90,up:180,down:180}[face],pitch=face==='up'?90:face==='down'?-90:0;
  // The legacy texture categories remain valid block states for existing saves.

  const existing = dimension.getEntities({ type: TYPE, location: position, maxDistance: 1 })
    .filter(entity => entity.getDynamicProperty(KEY) === key);
  if (!itemId) {
    for (const entity of existing) forget(entity);
    anchors.delete(key);
    return;
  }
  anchors.set(key, { dimension, location });
  let entity = existing.shift();
  for (const duplicate of existing) forget(duplicate);
  const created = !entity;
  if (created) {
    entity = dimension.spawnEntity(TYPE, position);
    entity.setDynamicProperty(KEY, key);
  }
  try {
    if(entity.getProperty('ava:display_pitch')!==pitch)entity.setProperty('ava:display_pitch',pitch);
    const label = `\u00a7f${Math.max(0, Math.floor(Number(count) || 0)).toLocaleString()}`;
    if (entity.nameTag !== label) entity.nameTag = label;
    const equipment = entity.getComponent('minecraft:equippable');
    if (equipment) {
      if (equipment.getEquipment(EquipmentSlot.Mainhand)?.typeId !== itemId &&
          !equipment.setEquipment(EquipmentSlot.Mainhand, new ItemStack(itemId, 1))) {
        throw new Error('Black Hole display could not equip stored item');
      }
    } else if (entity.getDynamicProperty(ITEM) !== itemId) {
      // Custom armor stands do not always expose the player equipment Script API.
      if (!/^[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(itemId)) throw new Error('Invalid display item identifier');
      const result = entity.runCommand(`replaceitem entity @s slot.weapon.mainhand 0 ${itemId} 1`);
      if (!result.successCount) throw new Error('Black Hole display equipment command failed');
      entity.setDynamicProperty(ITEM, itemId);
    }
    if (created || Math.hypot(entity.location.x - position.x, entity.location.y - position.y, entity.location.z - position.z) > 0.01 || entity.getRotation().y !== yaw) {
      entity.teleport(position, { rotation: { x: 0, y: yaw } });
    }
    reportedErrors.delete(key);
  } catch (error) {
    forget(entity);
    if (!reportedErrors.has(key)) {
      reportedErrors.add(key);
      console.warn(`Black Hole item display: ${error.message || error}`);
    }
    throw error;
  }
}


