function forgeAutoAlloy(b){const s=state(b);if(s.paused||s.autoAlloy===false||!smelteryStructure(b))return 0;const target=smelteryTarget(b),reserve=!s.alloyPinned&&target&&state(target).cast?.startsWith('ava:pattern_')?288:0;let metal=s.alloyPinned?s.alloyRecipe:undefined;if(!metal){const ready=Object.keys(forgeAlloys).filter(m=>forgeAlloyPlan(b,m).ready&&(!(reserve&&forgeAlloys[m].gold)||(s.molten?.gold||0)-forgeAlloys[m].gold>=reserve));if(ready.length>1){save(b,{...s,status:'Several alloys detected: select the metal/alloy above.'});return 0;}metal=ready[0];}if(!metal)return 0;const plan=forgeAlloyPlan(b,metal);let batches=0;while(batches<64&&(!(reserve&&forgeAlloys[metal].gold)||(state(b).molten?.gold||0)-forgeAlloys[metal].gold>=reserve)&&forgeAlloy(b,metal))batches++;if(batches){const consumed=[...Object.entries(plan.recipe).map(([m,n])=>n/144*batches+' '+forgeName(m)),...Object.entries(plan.catalysts).map(([id,n])=>n*batches+' '+forgeName(id))].join(' + ');save(b,{...state(b),alloyMessageUntil:Date.now()+7000,alloyMessage:'AUTO: used '+consumed+' -> '+plan.volume/144*batches+' '+forgeName(metal),status:'Auto-mixed '+batches+' '+forgeName(metal)+' batch(es)'});}return batches;}

// Factory fluids remain separate from water/lava, including across connected tanks.
const factoryFluids=['xp','pink'];
