function factoryTankKind(b){return factoryFluids.find(f=>tankCluster(b).some(t=>state(t)[f]>0||state(t).fluidLock===f));}
function factoryTankAccepts(tanks,fluid){return tanks.length>0&&tanks.every(t=>{const s=state(t);return !['lava','water',...factoryFluids].some(f=>f!==fluid&&s[f]>0)&&(!s.fluidLock||s.fluidLock===fluid);});}
function distributeFactoryFluid(tanks,fluid,total,syncUnchanged=true){if(!factoryTankAccepts(tanks,fluid))return false;const layers=[...new Set(tanks.map(t=>t.y))].sort((a,b)=>a-b);let left=Math.min(Math.max(0,total),tanks.length*16000);for(const y of layers){const layer=tanks.filter(t=>t.y===y).sort((a,b)=>a.x-b.x||a.z-b.z),n=Math.min(left,layer.length*16000),base=Math.floor(n/layer.length);let extra=n%layer.length;for(const t of layer){const s=state(t),next=base+(extra-->0?1:0);if(s[fluid]!==next||s.fluidLock!==fluid){save(t,{...s,[fluid]:next,fluidLock:fluid});syncTank(t);}else if(syncUnchanged)syncTank(t);}left-=n;}return true;}
function factoryFluidTotal(tanks,fluid){return tanks.reduce((n,t)=>n+(state(t)[fluid]||0),0);}
function factoryFluidName(fluid){return fluid==='xp'?'Liquid XP':'Pink Essence';}
function factoryPumpTick(pump){const queue=[pump],seen=new Set([key(pump)]),sources=[];for(let i=0;i<queue.length&&i<256;i++)for(const n of near(queue[i])){if(seen.has(key(n)))continue;seen.add(key(n));if(n.typeId==='ava:mob_grinder')sources.push(n);else if(n.typeId==='ava:transfer_pipe')queue.push(n);}if(!sources.length)return false;const tanks=fluidTargets(pump),clusters=[],used=new Set();for(const t of tanks){if(used.has(key(t)))continue;const group=tankCluster(t);group.forEach(v=>used.add(key(v)));clusters.push(group);}let moved=0;for(const source of sources)for(const fluid of factoryFluids){const s=state(source);let left=Math.min(1000,s[fluid]||0);for(const group of clusters){if(!left||!factoryTankAccepts(group,fluid))continue;const total=factoryFluidTotal(group,fluid),n=Math.min(left,group.length*16000-total);if(!n)continue;distributeFactoryFluid(group,fluid,total+n);left-=n;s[fluid]-=n;moved+=n;}save(source,s);}if(moved>0)beginPumpAnimation(pump);save(pump,{...state(pump),status:moved?'Pumped '+moved+' mB grinder fluids':'Grinder: needs separate XP / Pink Essence tanks; sneak-use empty tanks to select fluid'});return true;}
async function factoryTankUse(p,b){const tanks=tankCluster(b),fluid=factoryTankKind(b),held=inv(p)?.getItem(p.selectedSlotIndex);if(p.isSneaking){const totals=['lava','water',...factoryFluids].map(f=>[f,factoryFluidTotal(tanks,f)]);if(totals.some(([,n])=>n)){p.onScreenDisplay?.setActionBar('Drain connected tanks before changing their fluid filter');return true;}const r=await new ActionFormData().title('Tank Fluid Filter').body('Connected tanks share one fluid. Keep XP and Pink Essence tanks separated by a gap; join them with pipes.').button('Automatic / water / lava').button('Liquid XP only').button('Pink Essence only').show(p);if(r.canceled)return true;const f=[undefined,'xp','pink'][r.selection];if(r.selection<0||r.selection>2)return true;for(const t of tanks)save(t,{...state(t),fluidLock:f});return true;}if(held?.typeId==='ava:pink_essence_bucket'&&factoryTankAccepts(tanks,'pink')){const total=factoryFluidTotal(tanks,'pink');if(total+1000<=tanks.length*16000&&exchangeBucket(p,held.typeId,'minecraft:bucket'))distributeFactoryFluid(tanks,'pink',total+1000);return true;}if(!fluid)return false;const total=factoryFluidTotal(tanks,fluid);if(fluid==='pink'&&held?.typeId!=='minecraft:bucket'&&total>=1000){withdrawPinkSlime(p,b);return true;}if(fluid==='xp'&&held?.typeId==='minecraft:glass_bottle'&&total>=250){if(exchangeBucket(p,held.typeId,'minecraft:experience_bottle'))distributeFactoryFluid(tanks,fluid,total-250);}else if(fluid==='pink'&&held?.typeId==='minecraft:bucket'&&total>=1000){if(exchangeBucket(p,held.typeId,'ava:pink_essence_bucket'))distributeFactoryFluid(tanks,fluid,total-1000);}else p.onScreenDisplay?.setActionBar(factoryFluidName(fluid)+': '+total+' / '+tanks.length*16000+' mB | '+(fluid==='xp'?'Glass bottle: 250 mB':'Bucket: 1000 mB'));return true;}
function grinderTick(b){return factoryGrinderTick(b);}
function grinderWork(b){const s=state(b),out=grinderOutput(b);collectGrinderDrops(b,out);if(s.paused){save(b,{...state(b),status:'Paused'});return;}const facing=b.permutation.getState('minecraft:cardinal_direction')||'north',v=faceVectors[facing]||[0,0,-1],mobs=nearbyFactoryMobs(b,upgradeRange(b,s.range||4)).filter(e=>{const dx=e.location.x-b.x-.5,dz=e.location.z-b.z-.5;return dx*v[0]+dz*v[2]>=-.25&&Math.abs(e.location.y-b.y)<=2;});const mob=mobs[0];if(!mob){save(b,{...state(b),status:'Waiting for mobs '+facing+' of blades ('+upgradeRange(b,s.range||4)+' blocks)'});return;}const pig=mob.typeId==='minecraft:pig',pink=pig?Math.min(250,Math.max(0,16000-(s.pink||0))):0;const xp=Math.min(100,Math.max(0,16000-(s.xp||0)));if(!Array.from({length:out.size},(_,i)=>!out.getItem(i)).some(Boolean)){save(b,{...state(b),status:'Item output full: attach a Transfer Node'});return;}if(!power(b,80)){save(b,{...state(b),status:'Needs 80 W per mob'});return;}try{if(mob.kill()===false){save(b,{...state(b),status:'Mob resisted the grinder'});return;}}catch{save(b,{...state(b),status:'Mob could not be ground'});return;}save(b,{...state(b),xp:(s.xp||0)+xp,pink:(s.pink||0)+pink,kills:(s.kills||0)+1,status:'Ground '+forgeName(mob.typeId)+(xp?' | +'+xp+' mB XP':' | XP full, overflow skipped')+(pig?(pink?' | +'+pink+' mB Pink Essence':' | Pink Essence full, overflow skipped'):'')});beginGrinderAnimation(b);achievementAdd('mobs',1);if(pig)achievementAdd('pigs',1);}
function collectGrinderDrops(b,out){for(const e of b.dimension.getEntities({type:'minecraft:item',location:{x:b.x+.5,y:b.y+.5,z:b.z+.5},maxDistance:5})||[]){if(e.typeId!=='minecraft:item')continue;const item=e.getComponent('minecraft:item')?.itemStack;if(item&&bagFits(out,item)){out.addItem(item);e.remove();}}}
function grinderUse(p,b){openFactory(p,b);}
function conveyorTick(b){factoryConveyorTick(b);}
function rotateConveyor(p,b){const faces=['north','east','south','west'],face=faces[(faces.indexOf(b.permutation.getState('minecraft:cardinal_direction')||'north')+1)%4];b.setPermutation(b.permutation.withState('minecraft:cardinal_direction',face));p.onScreenDisplay?.setActionBar('Conveyor direction: '+oppositeFace[face].toUpperCase());}
