function smelteryAutomationTick(b){const s=state(b);if(s.drainJob183)return smelteryDrainTick183(b);if(!s.regulator||!s.autoCasting||s.paused)return;const shape=smelteryStructure(b);if(!shape)return;for(const drain of shape.drains)for(const f of near(drain))if(f.typeId==='ava:seared_faucet'){if(!state(f).auto)save(f,{...state(f),auto:true});forgePour(f);}}
async function smelteryOptions(p,b){const s=state(b),r=await new ActionFormData().title('Smeltery Automation').body('1. Transfer Node on source chest -> pipes -> Controller.\n2. Lava pump -> Seared Tank.\n3. Install Smeltery Regulator on Controller. Select a metal/alloy in its screen.\n4. Gold cast in Table; Faucet above it.\n5. Transfer Node on Table/Basin -> chest or MV Link.\n\nRegulator: '+(s.regulator?'installed':'not installed')+' | Auto casting: '+(s.autoCasting?'ON':'OFF')).button(s.autoCasting?'Stop auto casting':'Start auto casting').button('Flush selected molten metal (discard)').button('Open controller').show(p);if(r.canceled)return;if(r.selection===0){if(!state(b).regulator){p.sendMessage('Install a Smeltery Regulator by using it on the Controller. Faucets can also be toggled individually by sneak-use.');return;}setSmelteryAutomation(b,!state(b).autoCasting);}if(r.selection===1){const latest=state(b),m=latest.selected;if(m){save(b,{...latest,molten:{...latest.molten,[m]:0},status:'Flushed '+forgeName(m)});const shape=smelteryStructure(b);if(shape)forgePoolVisual(b,shape);}}if(r.selection===2)openSmeltery(p,b);}
