world.beforeEvents.playerBreakBlock.subscribe(e=>{if(packedBreakEvents207.has(e))return;const b=e.block,s=state(b);if(b.typeId==='ava:mob_grinder'&&(s.xp>0||s.pink>0||s.mobOutput?.some(v=>v?.amount>0))||b.typeId==='ava:tank'&&(s.water>0||factoryFluids.some(f=>s[f]>0)||s.fluidOutput?.some(v=>v?.amount>0))){e.cancel=true;system.run(()=>e.player.sendMessage('Empty items and drain fluids before breaking this machine.'));}});

// Pink Essence solidifies on extraction; bottles automate XP packaging.
function factoryTankBag(b){const out=storedOutput(b,'fluidOutput',9);return{size:10,hasItems:()=>state(b).fluidOutput?.some(v=>v?.amount>0)||factoryTankKind(b)==='pink'&&factoryFluidTotal(tankCluster(b),'pink')>=1000,getItem:i=>{if(i<9)return out.getItem(i);if(i!==9||factoryTankKind(b)!=='pink')return;const n=Math.min(64,Math.floor(factoryFluidTotal(tankCluster(b),'pink')/1000));if(n)return new ItemStack('ava:pink_slime',n);},setItem:(i,item)=>{if(i<9){out.setItem(i,item);return;}if(i!==9||factoryTankKind(b)!=='pink')return;const ts=tankCluster(b),total=factoryFluidTotal(ts,'pink'),visible=Math.min(64,Math.floor(total/1000));if(item&&item.typeId!=='ava:pink_slime')return;const removed=visible-(item?.amount||0);if(removed>0)distributeFactoryFluid(ts,'pink',total-removed*1000);},addItem:item=>{if(item.typeId!=='minecraft:glass_bottle'||factoryTankKind(b)!=='xp')return item;const ts=tankCluster(b),total=factoryFluidTotal(ts,'xp');let count=Math.min(item.amount,Math.floor(total/250));if(!count)return item;const bottle=new ItemStack('minecraft:experience_bottle',count);if(!bagFits(out,bottle))return item;const rest=out.addItem(bottle),made=count-(rest?.amount||0);if(made)distributeFactoryFluid(ts,'xp',total-made*250);if(made<item.amount){const left=item.clone();left.amount-=made;return left;}}};}

const pinkGeneratorRate=2000,pinkGeneratorCapacity=200000,pinkGeneratorFuelSeconds=20;
const factoryHosts=new Map(),factoryViewers=new Map(),factoryControls=[41,42,43];
function factoryHost(b){return machineHost216(b,'factoryHost','ava:factory_inventory');}
function factoryRange(b,start,size){const c=factoryHost(b)?.getComponent('minecraft:inventory')?.container;if(!c)return;return{size,hasItems:()=>Array.from({length:size},(_,i)=>c.getItem(start+i)).some(Boolean),getItem:i=>i>=0&&i<size?c.getItem(start+i):undefined,setItem:(i,item)=>{if(i>=0&&i<size)c.setItem(start+i,item);},addItem(item){let left=item.amount;for(let i=0;i<size&&left;i++){const old=this.getItem(i);if(old&&!old.isStackableWith(item))continue;const n=Math.min(left,(item.maxAmount||64)-(old?.amount||0));if(!n)continue;const next=old||item.clone();next.amount=(old?.amount||0)+n;this.setItem(i,next);left-=n;}if(left){const rest=item.clone();rest.amount=left;return rest;}}};}
function grinderOutput(b){return factoryRange(b,0,27)||storedOutput(b,'mobOutput');}
function pinkGeneratorInput(b){return factoryRange(b,0,9)||storedOutput(b,'pinkFuel',9);}
function pinkGeneratorBag(b){const c=pinkGeneratorInput(b);return{size:9,hasItems:c.hasItems,getItem:()=>undefined,setItem(){},addItem:item=>item.typeId==='ava:pink_slime'?c.addItem(item):item};}
function ensureFactoryHost(b){let host=factoryHost(b);if(!host&&b.typeId==='ava:nuclear_reactor'){repairReactorHost283(b);host=factoryHost(b);}if(!host){const s=state(b);if(s.factoryHost)return;host=b.dimension.spawnEntity('ava:factory_inventory',{x:b.x+.5,y:b.y-.0005,z:b.z+.5});host.nameTag=b.typeId==='ava:nuclear_reactor'?'ava.nuclear.native.ui':b.typeId==='ava:mob_grinder'?'ava.grinder.native.ui':b.typeId==='ava:combustion_generator'?'ava.combustion.native.ui':'ava.pink_generator.native.ui';host.setDynamicProperty('ava:block',{x:b.x,y:b.y,z:b.z});save(b,{...s,factoryHost:host.id});const c=host.getComponent('minecraft:inventory').container,field=b.typeId==='ava:nuclear_reactor'?'nuclearSlots279':b.typeId==='ava:mob_grinder'?'mobOutput':b.typeId==='ava:combustion_generator'?'combustionEscrow182':'pinkFuel',size=b.typeId==='ava:nuclear_reactor'?18:b.typeId==='ava:mob_grinder'?27:9,old=storedOutput(b,field,size);for(let i=0;i<size;i++){const item=old.getItem(i);if(item){c.setItem(i,item);old.setItem(i);}}for(let i=size;i<54;i++)c.setItem(i,uiToken());}factoryHosts.set(host.id,{b,host});markReactorHost283(b);hideUiName(host);return host;}
function factoryHasItems(b){if(b.typeId==='ava:nuclear_reactor')return hasOutput(reactorInput279(b))||hasOutput(reactorOutput279(b))||(stateValue240(b,'fuelEnergy279')||0)>0;const s=state(b),host=factoryHost(b);if(s.factoryHost&&!host)return true;const c=b.typeId==='ava:mob_grinder'?grinderOutput(b):pinkGeneratorInput(b);return hasOutput(c);}
function factoryTankGroups(root){const queue=[root],seen=new Set([key(root)]),groups=[],tanksSeen=new Set();for(let i=0;i<queue.length&&i<256;i++)for(const n of near(queue[i])){if(seen.has(key(n)))continue;seen.add(key(n));if(!['ava:transfer_pipe','ava:fluid_pump','ava:tank'].includes(n.typeId))continue;queue.push(n);if(n.typeId==='ava:tank'&&!tanksSeen.has(key(n))){const group=tankCluster(n);group.forEach(t=>tanksSeen.add(key(t)));groups.push(group);}}return groups;}
function exportGrinderFluids(b){if(!factoryFluids.some(fluid=>stateValue240(b,fluid)>0))return 0;const groups=factoryTankGroups(b);let moved=0;for(const fluid of factoryFluids){const s=state(b);let left=Math.min(1000,s[fluid]||0);if(!left)continue;const ordered=groups.slice().sort((a,c)=>Number(factoryTankKind(c[0])===fluid)-Number(factoryTankKind(a[0])===fluid));for(const group of ordered){if(!left||!factoryTankAccepts(group,fluid))continue;const total=factoryFluidTotal(group,fluid),amount=Math.min(left,group.length*16000-total);if(!amount)continue;if(distributeFactoryFluid(group,fluid,total+amount)){left-=amount;s[fluid]-=amount;moved+=amount;}}save(b,s);}return moved;}
function factoryGrinderTick(b){if(!ensureFactoryHost(b))return;try{grinderWork(b);}finally{refreshGrinderAnimation(b);exportGrinderFluids(b);}}
function pinkGeneratorTick(b){if(!ensureFactoryHost(b))return;const s=state(b);if(s.paused){s.status='Paused';save(b,s);paintFactory(b);return;}if((s.energy||0)+pinkGeneratorRate>pinkGeneratorCapacity){s.status='Energy buffer full; fuel preserved';save(b,s);paintFactory(b);return;}if(!(s.burn>0)){const c=pinkGeneratorInput(b);let slot=-1;for(let i=0;i<c.size;i++)if(c.getItem(i)?.typeId==='ava:pink_slime'){slot=i;break;}if(slot<0){s.status='Needs Pink Slime | Feed by Transfer Node';save(b,s);paintFactory(b);return;}const item=c.getItem(slot);if(item.amount===1)c.setItem(slot);else{item.amount--;c.setItem(slot,item);}s.burn=pinkGeneratorFuelSeconds;}s.burn--;s.energy=(s.energy||0)+pinkGeneratorRate;achievementAdd('watts',pinkGeneratorRate);s.status='Generating '+pinkGeneratorRate+' W/s | '+s.burn+'s fuel left';save(b,s);paintFactory(b);}
function openFactory(p,b){const host=ensureFactoryHost(b);if(!host)return;factoryViewers.set(host.id,p);paintFactory(b);armActivator(host,true);}
