function achievementRecord(p){try{const s=JSON.parse(p.getDynamicProperty('ava:achievements')||'{}');return{done:Array.isArray(s.done)?s.done:[],claimed:Array.isArray(s.claimed)?s.claimed:[]};}catch{return{done:[],claimed:[]};}}
function achievementInventory(p){const result={},c=inv(p);if(c)for(let i=0;i<c.size;i++){const item=c.getItem(i);if(item)result[item.typeId]=(result[item.typeId]||0)+item.amount;}const equipped=p.getComponent('minecraft:equippable');for(const slot of ['Head','Chest','Legs','Feet']){const item=equipped?.getEquipment?.(EquipmentSlot?.[slot]||slot);if(item)result[item.typeId]=(result[item.typeId]||0)+item.amount;}return result;}
function achievementProgress(g,items){if(Array.isArray(g.target))return Math.min(...g.target.map(id=>items[id]||0));return g.target.startsWith('@')?achievementTotal(g.target.slice(1)):items[g.target]||0;}
function achievementScan(p,notify=true){const s=achievementRecord(p),items=achievementInventory(p),newGoals=[];for(const g of achievementGoals)if(!s.done.includes(g.id)&&achievementProgress(g,items)>=g.amount){s.done.push(g.id);newGoals.push(g);}if(newGoals.length){p.setDynamicProperty('ava:achievements',JSON.stringify(s));if(notify)p.sendMessage('§aAchievement complete: '+newGoals.map(g=>g.title).join(', ')+'§r. Claim rewards in your Progression Book.');}return s;}
function achievementClaim(p,id){const g=achievementGoals.find(g=>g.id===id),s=achievementScan(p,false);if(!g||!s.done.includes(id)||s.claimed.includes(id))return false;const c=inv(p),before=Array.from({length:c.size},(_,i)=>c.getItem(i));try{const left=c.addItem(new ItemStack(g.reward,g.count));if(left){for(let i=0;i<c.size;i++)c.setItem(i,before[i]);p.sendMessage('Make room for the whole reward, then claim again.');return false;}s.claimed.push(id);p.setDynamicProperty('ava:achievements',JSON.stringify(s));return true;}catch(error){for(let i=0;i<c.size;i++)c.setItem(i,before[i]);throw error;}}
