 if(!chapter){const f=achievementForm(s.done.length/achievementGoals.length).body('YOUR FACTORY JOURNAL\n\nCompleted: '+s.done.length+'/'+achievementGoals.length+' | Rewards ready: '+s.done.filter(id=>!s.claimed.includes(id)).length+'\n\nProduction totals are shared by this world. Collection goals and rewards belong to each player. Checked goals stay completed. Production counting starts with this update.');for(const ch of chapters){const list=achievementGoals.filter(g=>g.chapter===ch);f.button(ch+'  '+list.filter(g=>s.done.includes(g.id)).length+'/'+list.length,'textures/ui/ava_goal_book');}const r=await f.show(p);if(r.canceled)break;chapter=chapters[r.selection];if(!chapter)break;continue;}
