// Polymer factory progression. Three persistent, removable upgrade slots per machine.
const advancedUpgradeMachines=new Set(['ava:harvester','ava:mob_grinder','ava:pulverizer','ava:pressure_reactor','ava:autonomous_activator']);
const upgradeItems={'ava:speed_upgrade':'speed','ava:range_upgrade':'range','ava:efficiency_upgrade':'efficiency'};
function upgradeCount(b,kind){return advancedUpgradeMachines.has(b.typeId)?machineUpgrades(b).filter(id=>upgradeItems[id]===kind).length:0;}
function upgradeSpeed(b){return 1+upgradeCount(b,'speed');}
function upgradeRange(b,base){return base+upgradeCount(b,'range')*2;}
