// A portable MV host has no physical ava:block. Authorize its owning remote
// instead of running the physical terminal path, which parks unrelated hosts.
function wirelessControllerInteract(e){
 const p=e.player,host=e.target,session=wirelessControllers.get(p.id),ctx=mvNativeRuntime?.contexts.get(host.id);
 const fail=message=>{e.cancel=true;system.run(()=>{if(host.getDynamicProperty('ava_mv:owner')===p.id)armActivator(host,false);p.onScreenDisplay?.setActionBar(message);});};
 if(host.getDynamicProperty('ava_mv:owner')!==p.id){fail('This remote belongs to another player');return;}
 if(!controllerItem(p)||p.isSneaking){fail('Hold the linked remote and release sneak to open');return;}
 if(!session||session.host.id!==host.id||!ctx||ctx.player.id!==p.id){fail('Use your remote again to prepare storage');return;}
 const b=ctx.block;
 if(b?.typeId!=='ava:mv_system'||p.dimension.id!==host.dimension.id||!remoteMvAllowed(p,b)){fail('Remote link changed - use it again');return;}
 if(!mvCanOpen202(b)){fail('Bound MV needs 20 W to operate');return;}
 // Context is already prepared by the held-item loop. Leave this interaction
 // uncanceled so Bedrock opens this exact portable inventory, once.
}

