const forgeModifierItems151={ 'ava:reinforcement_plate':'reinforced','ava:efficiency_module':'efficiency','ava:fortune_module':'fortune'};
function applyForgeModifier151(p,toolSlot,modifierId){const bag=inv(p),tool=bag.getItem(toolSlot),modifier=forgeModifierItems151[modifierId];if(!modifier||!tool?.typeId.startsWith('ava:modular_'))throw Error('Choose a modular forge tool');let data;try{data=JSON.parse(tool.getDynamicProperty('ava:modular')||'null');}catch{}if(!data)throw Error('Use or assemble this tool first');if(modifier==='fortune'&&!tool.typeId.endsWith('_pickaxe'))throw Error('Fortune modules fit modular pickaxes');const mods=data.modifiers151||[];if(mods.includes(modifier)||mods.length>=3)throw Error('One of each modifier, maximum 3 per tool');const before=mvSnapshot(bag);if(modifier==='reinforced'){data.max+=Math.ceil(forgeToolStats(data.head,data.rod,data.binding).durability*.25);}else{const enchant=tool.getComponent('minecraft:enchantable');if(!enchant)throw Error('This tool cannot be enchanted');const id=modifier==='efficiency'?'efficiency':'fortune',level=modifier==='efficiency'?2:1;if(id==='fortune'&&enchant.getEnchantment('silk_touch'))throw Error('Remove Silk Touch before adding Fortune');if((enchant.getEnchantment(id)?.level||0)>=level)throw Error('Tool already has that enchantment or better');enchant.addEnchantment({type:EnchantmentTypes.get(id),level});}data.modifiers151=[...mods,modifier];tool.setDynamicProperty('ava:modular',JSON.stringify(data));tool.setLore([...(tool.getLore()||[]).filter(line=>!line.startsWith('Modifiers:')),'Modifiers: '+data.modifiers151.join(', ')]);const d=tool.getComponent('minecraft:durability');if(d)d.damage=Math.min(d.maxDurability-1,Math.floor(data.used/data.max*d.maxDurability));try{if(!take(p,modifierId))throw Error('Hold the modifier item');bag.setItem(toolSlot,tool);}catch(error){for(let i=0;i<bag.size;i++)bag.setItem(i,before[i]);throw error;}return true;}
async function forgeModifierMenu151(p){if(progressionMenus151.has(p.id))return;progressionMenus151.add(p.id);try{const bag=inv(p),modifierId=bag.getItem(p.selectedSlotIndex)?.typeId,slots=[];const form=new ActionFormData().title('TOOL FORGE MODIFIERS').body('One of each modifier per modular tool. Existing material traits remain.');for(let i=0;i<bag.size;i++){const item=bag.getItem(i);if(item?.typeId.startsWith('ava:modular_')){slots.push(i);form.button(item.nameTag||progressionNames151(item.typeId));}}form.button('Cancel');const r=await form.show(p);if(!r.canceled&&r.selection<slots.length){applyForgeModifier151(p,slots[r.selection],modifierId);p.sendMessage?.('Modifier installed.');}}catch(error){p.sendMessage?.('Tool Forge: '+error.message);}finally{progressionMenus151.delete(p.id);}}
function progressionUse151(p){const id=inv(p)?.getItem(p.selectedSlotIndex)?.typeId;if(id==='ava:recipe_book'){p.onScreenDisplay?.setActionBar('Recipe Book retired | Use the Universal Crafter or PDF guide');return;}if(id==='ava:crafting_planner')return openPlannerHud154(p);}
function progressionInteract151(e){const p=e.player,id=inv(p)?.getItem(p.selectedSlotIndex)?.typeId;if(id==='ava:crafting_planner'&&e.block.typeId==='ava:universal_crafter'&&p.isSneaking){e.cancel=true;if(e.isFirstEvent)system.run(()=>{p.sendMessage?.('Set a recipe in the crafter, then choose Craft or Keep stock.');});return true;}if(forgeModifierItems151[id]&&e.block.typeId==='ava:tool_forge'&&p.isSneaking){e.cancel=true;if(e.isFirstEvent)system.run(()=>forgeModifierMenu151(p));return true;}if(id==='ava:crafting_planner'&&(!hasMachineHud(e.block)||p.isSneaking)){e.cancel=true;if(e.isFirstEvent)system.run(()=>progressionUse151(p));return true;}return false;}


