for(let slot=0;slot<=35;slot++){const item=c.getItem(slot);if(item?.typeId==='ava:book_ui_token'&&item.amount===64)continue;if(item&&item.typeId!=='ava:book_ui_token'){if(returnBookInput153(s,slot))c.setItem(slot,bookToken153());changed=true;continue;}c.setItem(slot,bookToken153());const d=recipeHudData153(s);if(slot<15)bookSelect153(s,s.shown?.[slot]);else if(slot===15)s.page=Math.max(0,s.page-1);else if(slot===16)s.page=Math.min(d.pages-1,s.page+1);else if(slot===17||slot===18){s.mode=slot===17?'recipes':'uses';s.recipe=0;s.ingredientPage=0;}else if(slot===19||slot===20){s.recipe=(s.recipe+(slot===19?-1:1)+Math.max(1,d.rows.length))%Math.max(1,d.rows.length);s.ingredientPage=0;}else if(slot===21){s.query='';s.page=0;s.message='';}else if(slot===22){s.query='@no_match';s.selected=undefined;s.page=0;s.message='No match. Try an item name or word; All items shows the catalog.';}else if(slot===23){const old=s.history.pop();if(old)Object.assign(s,old);}else if(slot===24||slot===25){const pages=Math.max(1,Math.ceil((d.r?.inputs.length||0)/9));s.ingredientPage=((s.ingredientPage||0)+(slot===24?-1:1)+pages)%pages;}else if(slot>=26&&slot<=34)bookSelect153(s,s.cells?.[slot-26]?.id);else if(slot===35)bookSelect153(s,d.r?.output);changed=true;break;}
