function openRecipeHud153(p,prime=false,planner=false){const sessionKey=planner?p.id+':planner':p.id;let s=recipeHud153.get(sessionKey);if(!s||!entityAlive160(s.host)){const property=planner?'ava:planner_hud154':'ava:recipe_hud153',old=p.getDynamicProperty(property),prior=typeof old==='string'?world.getEntity(old):undefined,host=prior?.getDynamicProperty('ava:book_owner')===p.id?prior:p.dimension.spawnEntity(planner?'ava:crafting_planner_inventory':'ava:recipe_book_inventory',p.location);host.nameTag=planner?'ava.planner.native.ui':'ava.recipebook.native.ui';host.setDynamicProperty('ava:book_owner',p.id);p.setDynamicProperty(property,host.id);s={player:p,host,planner,quantity:1,query:'',page:0,mode:'recipes',recipe:0,ingredientPage:0,selected:undefined,history:[],open:false,cooldown:0};recipeHud153.set(sessionKey,s);const c=inv(host);for(let i=0;i<=(planner?39:35);i++)if(!c.getItem(i)||bookProtocol157(c.getItem(i)))c.setItem(i,bookToken153());for(let g=0;g<recipeBookFind153.pool.length;g++){const slot=recipeBookFind153.pool[g],payload=recipeBookFind153.payloads[g],old=c.getItem(slot);if(old&&!bookProtocol157(old))continue;if(old?.amount===64&&old.nameTag==='\u00a7r'+payload.tag&&JSON.stringify(old.getLore())===JSON.stringify(['[recipebook:find153]',...payload.lines]))continue;const token=bookToken153(payload.tag);token.setLore(['[recipebook:find153]',...payload.lines]);c.setItem(slot,token);}if(planner)paintPlannerHud154(s);else paintRecipeHud153(s);}if(!prime)nativeHudOwner157.set(p.id,s.host.id);s.parked156=false;hideUiName(s.host);if(!s.open){const h=p.getHeadLocation?.()||{x:p.location.x,y:p.location.y+1.6,z:p.location.z},v=p.getViewDirection?.()||{x:0,y:0,z:1};s.host.teleport({x:h.x+v.x*1.25,y:h.y+v.y*1.25-.45,z:h.z+v.z*1.25},{dimension:p.dimension});}armActivator(s.host,(system.currentTick||0)>=(s.cooldown||0));return s;}
world.beforeEvents.playerInteractWithEntity.subscribe(e=>{const planner=e.target.typeId==='ava:crafting_planner_inventory';if(!planner&&e.target.typeId!=='ava:recipe_book_inventory')return;const s=recipeHud153.get(planner?e.player.id+':planner':e.player.id),held=planner?'ava:crafting_planner':'ava:recipe_book';if(e.target.getDynamicProperty('ava:book_owner')!==e.player.id||inv(e.player)?.getItem(e.player.selectedSlotIndex)?.typeId!==held||planner&&e.player.isSneaking){e.cancel=true;if(planner&&e.player.isSneaking)system.run(()=>parkPortableUi(e.target));return;}if(s)s.open=true;else system.run(()=>{const active=openRecipeHud153(e.player,true,planner);active.open=true;});});
