const reactorCoolantCapacity280={'minecraft:copper_block':250000,'minecraft:iron_block':750000,'minecraft:gold_block':1500000,'minecraft:diamond_block':5000000,'minecraft:netherite_block':20000000};
function reactorCoolantSlot280(x,y,z,v){
 if(y)return y>0?'Top':'Bottom';
 if(x===-v[0]&&z===-v[2])return 'Back';
 const right=[-v[2],v[0]];return x===right[0]&&z===right[1]?'Right':'Left';
}
function reactorCoolantSync280(s,shape){
 if(shape.unavailable)return;
 const old=s.coolant280||{},next={};s.coolantSpent280={...s.coolantSpent280};for(const slot of shape.cased||[])delete s.coolantSpent280[slot];
 for(const c of shape.coolers){
  const id=c.pos.x+','+c.pos.y+','+c.pos.z,prior=old[id],capacity=reactorCoolantCapacity280[c.id];
  next[id]={id:c.id,slot:c.slot,capacity,remaining:prior?.id===c.id&&Number.isFinite(prior.remaining)?Math.max(0,Math.min(capacity,prior.remaining)):capacity};delete s.coolantSpent280[c.slot];
 }
 s.coolant280=next;
}
function reactorCoolantLines280(s){
 const rows=Object.values(s.coolant280||{}),pct=r=>Math.max(0,Math.min(100,Math.ceil(100*r.remaining/r.capacity))),spent=Object.keys(s.coolantSpent280||{}).length>0,get=slot=>{const row=rows.find(r=>r.slot===slot);return row?pct(row)+'%':s.coolantSpent280?.[slot]?'0%':'--';};
 return ['Coolant: L '+get('Left')+' | R '+get('Right')+' | Back '+get('Back'),'Top '+get('Top')+' | Bottom '+get('Bottom')+' | Low '+(spent?'0%':rows.length?Math.min(...rows.map(pct))+'%':'--')];
}

// Named relay registry is read only on setup/menu actions, never during power ticks.
const relayMenus282=new Set(),relayRegistryKey282='ava:wireless_registry282:';
function relayRecords282(){const rows=[];for(let i=0;i<4;i++)try{const shard=JSON.parse(world.getDynamicProperty(relayRegistryKey282+i)||'[]');if(Array.isArray(shard))rows.push(...shard);}catch{}return rows;}
function relayWriteRecords282(rows){if(rows.length>256)throw Error('Wireless relay directory is full (256 named relays)');const before=Array.from({length:4},(_,i)=>world.getDynamicProperty(relayRegistryKey282+i));try{for(let i=0;i<4;i++)world.setDynamicProperty(relayRegistryKey282+i,JSON.stringify(rows.slice(i*64,(i+1)*64)));}catch(error){for(let i=0;i<4;i++)try{world.setDynamicProperty(relayRegistryKey282+i,before[i]);}catch{}throw error;}}
function relayName282(value){return String(value??'').replace(/[\u0000-\u001f\u007f\u00a7]/g,'').trim().slice(0,32);}
function relayRecord282(b){const s=state(b);return{id:s.wirelessId279,dimension:b.dimension.id,x:b.x,y:b.y,z:b.z,name:s.wirelessName282||'Power '+b.x+', '+b.y+', '+b.z,role:s.wirelessRole279||'transmitter',target:s.wirelessTarget279?.id};}
function relayTouch282(b){
 if(!stateValue240(b,'wirelessId279'))relayInitialize279(b);
 if(!stateValue240(b,'wirelessName282'))save(b,{...state(b),wirelessName282:relayRandomName286()});
 const row=relayRecord282(b),rows=relayRecords282().filter(r=>!(r.dimension===row.dimension&&r.x===row.x&&r.y===row.y&&r.z===row.z));rows.push(row);relayWriteRecords282(rows);return row;
}
function relaySourceRows282(b,query=''){
 const q=relayName282(query).toLowerCase(),me=stateValue240(b,'wirelessId279'),rows=relayRecords282(),alive=[];let changed=false;
 for(const row of rows){
  if(row.dimension!==b.dimension.id){alive.push(row);continue;}
  let current;try{current=b.dimension.getBlock({x:row.x,y:row.y,z:row.z});}catch{}
  if(current&&(current.typeId!=='ava:wireless_power_relay'||stateValue240(current,'wirelessId279')!==row.id)){changed=true;continue;}
  alive.push(row);
 }
 if(changed)relayWriteRecords282(alive);
 return alive.filter(r=>r.dimension===b.dimension.id&&r.id!==me&&r.role==='transmitter'&&(!q||(r.name+' '+r.x+' '+r.y+' '+r.z).toLowerCase().includes(q))).sort((a,b)=>a.name.localeCompare(b.name)||a.id.localeCompare(b.id));
}
function relayBind282(b,row){
 if(!row||row.dimension!==b.dimension.id||row.id===stateValue240(b,'wirelessId279'))throw Error('Choose another transmitter in this dimension');
 let target;try{target=b.dimension.getBlock({x:row.x,y:row.y,z:row.z});}catch{}
 if(target&&(target.typeId!=='ava:wireless_power_relay'||stateValue240(target,'wirelessId279')!==row.id||stateValue240(target,'wirelessRole279')!=='transmitter'))throw Error('That transmitter changed. Open the source list again.');
 const before=state(b);try{save(b,{...before,wirelessRole279:'receiver',wirelessTarget279:{dimension:row.dimension,x:row.x,y:row.y,z:row.z,id:row.id}});relayTouch282(b);}catch(error){save(b,before);throw error;}finally{invalidateNetworks();}
}
async function relayShow282(form,p){for(let n=0;n<8;n++){const r=await form.show(p);if(r.cancelationReason!=='UserBusy')return r;await new Promise(done=>system.runTimeout(done,2));}return{canceled:true};}
function relayMenuValid282(p,b,id){return p.isValid!==false&&b.typeId==='ava:wireless_power_relay'&&stateValue240(b,'wirelessId279')===id&&p.dimension?.id===b.dimension.id&&Math.hypot(p.location.x-b.x-.5,p.location.y-b.y-.5,p.location.z-b.z-.5)<=8;}
async function relayMenu282(p,b){
 if(relayMenus282.has(p.id))return;relayMenus282.add(p.id);
 try{
  let row=relayTouch282(b),id=row.id;
  while(relayMenuValid282(p,b,id)){
   row=relayRecord282(b);const s=state(b),target=s.wirelessTarget279,source=target?relayRecords282().find(r=>r.id===target.id):undefined;
   const form=new ActionFormData().title('Wireless Power Relay').body('Name: '+row.name+'\nRole: '+row.role+'\nLocation: '+b.x+', '+b.y+', '+b.z+'\nSource: '+(source?.name||(target?'Previously paired transmitter':'Not linked'))+'\nAvailable: '+availablePower(b).toLocaleString()+' W\n\nReceivers share the source\'s real energy. Both ends must be loaded.');
   const actions=[];form.button('Rename relay\nSet a recognizable location name','textures/items/ava_wireless_power_relay279');actions.push('rename');
   form.button('Connect to named transmitter\nBrowse or search this dimension','textures/items/ava_nuclear_reactor279');actions.push('connect');
   if(row.role==='receiver'){form.button('Use as transmitter\nSupply power to other receivers');actions.push('transmitter');form.button('Disconnect source\nKeep this receiver unpaired');actions.push('disconnect');}
   else{form.button('Connected receivers\nView saved receiver names');actions.push('receivers');}
   form.button('Close');actions.push('close');
   const result=await relayShow282(form,p);if(result.canceled||!relayMenuValid282(p,b,id))return;
   const action=actions[result.selection];if(action==='close')return;
   if(action==='rename'){
    const r=await relayShow282(new ModalFormData().title('Name Wireless Relay').textField('Relay name','Reactor Room, Tree Farm, Main Power',{defaultValue:row.name}),p);
    if(!r.canceled&&relayMenuValid282(p,b,id)){const name=relayName282(r.formValues?.[0]);if(!name){p.sendMessage('Enter a relay name.');continue;}save(b,{...state(b),wirelessName282:name});relayTouch282(b);}
   }else if(action==='connect'){
    let query='',page=0;
    while(relayMenuValid282(p,b,id)){
     const sources=relaySourceRows282(b,query),pages=Math.max(1,Math.ceil(sources.length/12));page=Math.min(page,pages-1);
     const list=new ActionFormData().title('Choose Power Transmitter').body((query?'Search: '+query+'\n':'')+'Page '+(page+1)+' / '+pages+' | '+sources.length+' sources\nChoose a name to pair this receiver.');
     const visible=sources.slice(page*12,page*12+12);for(const r of visible)list.button(r.name+'\n'+r.x+', '+r.y+', '+r.z);for(let empty=visible.length;empty<12;empty++)list.button('');
     list.button('Search names');list.button('Previous page');list.button('Next page');list.button('Back');
     const r=await relayShow282(list,p);if(r.canceled||!relayMenuValid282(p,b,id))break;
     if(r.selection<visible.length){relayBind282(b,visible[r.selection]);p.sendMessage('Wireless receiver connected to '+visible[r.selection].name+'.');break;}
     if(r.selection<12)continue;const at=r.selection-12;
     if(at===0){const search=await relayShow282(new ModalFormData().title('Search Power Sources').textField('Name or coordinates','Main Power',{defaultValue:query}),p);if(!search.canceled){query=relayName282(search.formValues?.[0]);page=0;}}
     else if(at===1)page=(page+pages-1)%pages;else if(at===2)page=(page+1)%pages;else break;
    }
   }else if(action==='transmitter'){save(b,{...state(b),wirelessRole279:'transmitter',wirelessTarget279:undefined});relayTouch282(b);invalidateNetworks();}
   else if(action==='disconnect'){save(b,{...state(b),wirelessRole279:'receiver',wirelessTarget279:undefined});relayTouch282(b);invalidateNetworks();}
   else if(action==='receivers'){
    const receivers=relayRecords282().filter(r=>r.target===id&&r.role==='receiver');const text=receivers.slice(0,64).map(r=>r.name+' ('+r.x+', '+r.y+', '+r.z+')').join('\n');await relayShow282(new ActionFormData().title('Connected Receivers').body(text||'No receivers paired yet. Open a receiver and choose this transmitter by name.').button('Back'),p);
   }
  }
 }catch(error){p.sendMessage?.('Wireless relay: '+String(error.message||error));}finally{relayMenus282.delete(p.id);}
}
