 const keys=[];for(const pos of next){const id='ava:m_'+b.dimension.id+'_'+pos.x+'_'+pos.y+'_'+pos.z;let map=reactorPorts284.get(id);if(!map){if(reactorPorts284.size>=4096)continue;map=new Map();reactorPorts284.set(id,map);}map.set(owner,{dimension:b.dimension.id,x:b.x,y:b.y,z:b.z});keys.push(id);}
 keys.stamp=stamp;if(keys.length)reactorPortOwners284.set(owner,keys);else reactorPortOwners284.delete(owner);
