async function relayPersistent284(p,b){
 if(typeof relayUi284==='undefined'||!relayUi284.CustomForm)return relayMenu282(p,b);
 if(relaySessions284.has(p.id)||relayMenus282.has(p.id))return;
 const UI=relayUi284;let session;
 try{
  const row=relayTouch282(b),id=row.id,name=new UI.ObservableString(row.name,{clientWritable:true}),query=new UI.ObservableString('',{clientWritable:true}),status=new UI.ObservableString(relayPowerStatus284(b)),notice=new UI.ObservableString(''),pageLabel=new UI.ObservableString('');
  const sourceLabels=Array.from({length:8},()=>new UI.ObservableString('')),sourceVisible=Array.from({length:8},()=>new UI.ObservableBoolean(false));
  const form=new UI.CustomForm(p,'Wireless Power Relay');
  session={p,b,id,form,name,query,status,notice,pageLabel,sourceLabels,sourceVisible,page:0,rows:[],visible:[],closed:false};relaySessions284.set(p.id,session);
  const valid=()=>relayMenuValid282(p,b,id),refresh=()=>{if(!valid())return;status.setData(relayPowerStatus284(b));};
  const run=fn=>()=>{if(!valid()){try{form.close();}catch{}return;}try{fn();}catch(error){notice.setData(String(error.message||error));}};
  const render=()=>{const pages=Math.max(1,Math.ceil(session.rows.length/8));session.page=Math.max(0,Math.min(session.page,pages-1));session.visible=session.rows.slice(session.page*8,session.page*8+8);pageLabel.setData('Transmitters: '+session.rows.length+' | Page '+(session.page+1)+' / '+pages);for(let i=0;i<8;i++){const r=session.visible[i];sourceLabels[i].setData(r?r.name+' ('+r.x+', '+r.y+', '+r.z+')':'');sourceVisible[i].setData(!!r);}};
  const find=()=>{session.rows=relaySourceRows282(b,query.getData());session.page=0;render();};
  form.closeButton().label(status).textField('Name',name,{description:'Rename this relay; existing connections stay linked.'});
  form.button('Save name',run(()=>{Promise.resolve(typeof name.getFilteredText==='function'?name.getFilteredText(p):name.getData()).then(text=>{if(!valid()||relaySessions284.get(p.id)!==session)return;const clean=typeof text==='string'?relayName282(text):'';if(!clean){notice.setData('Enter a valid name (up to 32 characters).');return;}save(b,{...state(b),wirelessName282:clean});relayTouch282(b);name.setData(clean);notice.setData('Saved name: '+clean);refresh();}).catch(error=>notice.setData(String(error.message||error)));}));
  form.textField('Find transmitter',query,{description:'Type a name or coordinates, then press Find.'}).button('Find',run(find)).label(pageLabel);
  for(let i=0;i<8;i++)form.button(sourceLabels[i],run(()=>{const row=session.visible[i];if(!row)return;relayBind282(b,row);notice.setData('Connected to '+row.name);refresh();find();}),{visible:sourceVisible[i]});
  form.button('Previous page',run(()=>{const pages=Math.max(1,Math.ceil(session.rows.length/8));session.page=(session.page+pages-1)%pages;render();}));
  form.button('Next page',run(()=>{const pages=Math.max(1,Math.ceil(session.rows.length/8));session.page=(session.page+1)%pages;render();}));
  form.button('Use this relay as transmitter',run(()=>{save(b,{...state(b),wirelessRole279:'transmitter',wirelessTarget279:undefined});relayTouch282(b);invalidateNetworks();notice.setData('Transmitter: connect it to a power source.');refresh();find();}));
  form.button('Disconnect source',run(()=>{save(b,{...state(b),wirelessRole279:'receiver',wirelessTarget279:undefined});relayTouch282(b);invalidateNetworks();notice.setData('Receiver disconnected.');refresh();}));
  form.label(notice);find();await form.show();
 }catch(error){try{p.sendMessage?.('Wireless relay: '+String(error.message||error));}catch{}}
 finally{if(session)session.closed=true;if(relaySessions284.get(p.id)===session)relaySessions284.delete(p.id);}
}
